import data.glitch_lib

branch_attr_keywords := {"case", "cases", "choice", "choices", "branch", "branches", "when", "match", "switch", "selector", "select", "mapping", "states", "state", "transitions", "conditions"}
fallback_keywords := {"default", "otherwise", "else", "fallback", "catch_all", "catchall", "unknown"}

