lookup_method_names := {"get", "lookup", "select", "index", "fetch"}

branch_attr_name(name) {
    kw := branch_attr_keywords[_]
    glitch_lib.contains(name, kw)
}

expr_signature(expr) = sig {
    sig := expr.code
    sig != ""
} else = sig {
    expr.ir_type == "VariableReference"
    sig := expr.value
} else = sig {
    expr.ir_type == "String"
    sig := expr.value
}

bool_case(cond, sig, val) {
    cond.ir_type == "Equal"
    cond.left.ir_type == "Boolean"
    val := cond.left.value
    sig := expr_signature(cond.right)
}

bool_case(cond, sig, val) {
    cond.ir_type == "Equal"
    cond.right.ir_type == "Boolean"
    val := cond.right.value
    sig := expr_signature(cond.left)
}

bool_case(cond, sig, val) {
    cond.ir_type == "Not"
    sig := expr_signature(cond.expr)
    val := false
}

bool_case(cond, sig, val) {
    cond.ir_type == "VariableReference"
    sig := expr_signature(cond)
    val := true
}

bool_case(cond, sig, val) {
    cond.ir_type == "Access"
    sig := expr_signature(cond)
    val := true
}

chain_node(node, node) {
    node.ir_type == "ConditionalStatement"
}

chain_node(node, n) {
    node.ir_type == "ConditionalStatement"
    node.else_statement != null
    chain_node(node.else_statement, n)
}

chain_nodes(top) = nodes {
    nodes := {n | chain_node(top, n)}
}

chain_length(top) = n {
    n := count(chain_nodes(top))
}

branch_is_default(branch) {
    branch.is_default == true
}

branch_is_default(branch) {
    branch.condition.ir_type == "Null"
}

branch_is_default(branch) {
    branch.condition.ir_type == "Undef"
}

branch_is_default(branch) {
    branch.type == "IF"
    branch.condition.ir_type == "Boolean"
    branch.condition.value == true
}

chain_has_default(top) {
    cn := chain_nodes(top)
    b := cn[_]
    branch_is_default(b)
}

has_parent_else(cond, conds) {
    parent := conds[_]
    parent.else_statement == cond
}

is_chain_top(cond, conds) {
    not has_parent_else(cond, conds)
}

boolean_exhaustive_chain(top) {
    cn := chain_nodes(top)
    count(cn) == 2
